#include <iostream>
#include <string>
#include <array>
#include <memory>
#include <numeric>

struct Account {
    std::string owner;
    double balance;
};

int main() {
    // 1. std::string provides safety and intuitive operators
    std::string greeting = "Account: ";
    greeting += "Alice";

    // 2. std::array retains size and supports bounds safety
    std::array<int, 4> transaction_ids = {101, 102, 103, 104};

    // 3. std::unique_ptr guarantees automatic deterministic deallocation
    auto acc = std::make_unique<Account>(Account{"Alice", 1500.50});

    std::cout << greeting << "\n";
    std::cout << "Owner: " << acc->owner << ", Balance: " << acc->balance << "\n";
    std::cout << "Transactions count: " << transaction_ids.size() << "\n";
    std::cout << "First TX: " << transaction_ids.at(0) << "\n";

    return 0;
}
